\title{Factorial Coordinates for Finite Permutations\\\large A Canonical Classification by Bounded Mixed-Radix Codes}
\author{Aristotle}
\date{15 July 2026}

\begin{document}
\maketitle

\begin{abstract}
For each natural number $k$, consider digit vectors $c=(c_0,\ldots,c_{k-1})$ satisfying $0\le c_i<i+1$, with factoradic value $V_k(c)=\sum_{i=0}^{k-1}c_i i!$. We establish a complete classification of these codes, numerical ranks, and permutations of $k$ elements. Factorial evaluation always lies in $[0,k!)$ and is injective; because the code space has cardinality $k!$, it is a bijection onto the integers from $0$ to $k!-1$. A recursive quotient--remainder decomposition then gives a bijection between this rank interval and permutations: at the successor step one chooses one of $k+1$ positions for a distinguished element and recursively permutes the remaining elements. The composite correspondence has rank exactly equal to factoradic value. We derive unique representation, equality criteria, factorial enumeration, executable ranking and unranking algorithms, and applications to search, random generation, and compact indexing.
\end{abstract}

\section{Introduction}

The equality between the number of permutations of $k$ objects and $k!$ is elementary. A stronger structural question asks whether each permutation has a canonical integer address below $k!$, represented by arithmetic coordinates that mirror the recursive choices used to build that permutation.

The factorial number system uses place values $0!,1!,\ldots,(k-1)!$ and permits the digit in place $i$ to range from $0$ through $i$. The number of legal vectors is
\[
\prod_{i=0}^{k-1}(i+1)=k!.
\]
Equal cardinalities alone supply no distinguished correspondence. Our purpose is to construct a reversible classification in which arithmetic quotient--remainder decomposition agrees with combinatorial removal and insertion.

Throughout, $\N=\{0,1,2,\ldots\}$, $[k]=\{0,1,\ldots,k-1\}$, and $\Sn_k$ is the set of permutations of $[k]$. We take $0!=1$ and $(k+1)!=(k+1)k!$.

\section{Factorial codes}

\begin{definition}[Factorial-code space]
For $k\in\N$, define
\[
\C_k=\prod_{i=0}^{k-1}\{0,1,\ldots,i\}.
\]
Thus $c\in\C_k$ is a vector $(c_0,\ldots,c_{k-1})$ with $0\le c_i<i+1$. The empty product $\C_0$ contains one empty code.
\end{definition}

\begin{definition}[Factoradic evaluation]
For $c\in\C_k$, let
\[
V_k(c)=\sum_{i=0}^{k-1}c_i i!.
\]
Digits are indexed in ascending place order.
\end{definition}

\begin{proposition}[Recursive splitting]
If $c\in\C_{k+1}$ and $c^-=(c_0,\ldots,c_{k-1})$, then
\[
V_{k+1}(c)=c_k k!+V_k(c^-).
\]
\end{proposition}
\begin{proof}
Split the defining sum into the terms below index $k$ and the final term.
\end{proof}

\begin{theorem}[Factoradic range]
For every $k\in\N$ and $c\in\C_k$,
\[
0\le V_k(c)<k!.
\]
\end{theorem}
\begin{proof}
Induct on $k$. The empty code has value $0<1=0!$. At the successor step, recursive splitting and the induction hypothesis give
\[
V_{k+1}(c)=c_k k!+V_k(c^-),
\]
where $0\le c_k\le k$ and $0\le V_k(c^-)<k!$. Hence
\[
V_{k+1}(c)\le k k!+(k!-1)=(k+1)!-1.
\]
Nonnegativity is immediate.
\end{proof}

For a fixed final digit $c_k=q$, the values occupy the half-open block $[qk!,(q+1)k!)$. The $k+1$ blocks partition $[0,(k+1)!)$.

\begin{theorem}[Uniqueness of bounded factorial expansion]
For $c,d\in\C_k$,
\[
V_k(c)=V_k(d)\quad\Longrightarrow\quad c=d.
\]
\end{theorem}
\begin{proof}
Induct on $k$. The length-zero case is immediate. At length $k+1$, write
\[
V_{k+1}(c)=c_k k!+r,\qquad V_{k+1}(d)=d_k k!+s,
\]
with $r=V_k(c^-)$ and $s=V_k(d^-)$. The range theorem gives $0\le r,s<k!$. Uniqueness of quotient and remainder after division by $k!$ yields $c_k=d_k$ and $r=s$. The induction hypothesis then gives $c^-=d^-$.
\end{proof}

\begin{proposition}[Cardinality]
For every $k\in\N$, $|\C_k|=k!$.
\end{proposition}
\begin{proof}
Digit $c_i$ has $i+1$ independent choices, so
\[
|\C_k|=\prod_{i=0}^{k-1}(i+1)=k!.
\]
The empty-product case gives $|\C_0|=1$.
\end{proof}

\begin{corollary}[Complete numerical classification]
The map
\[
V_k:\C_k\longrightarrow\{0,1,\ldots,k!-1\}
\]
is a bijection. Therefore every integer $n$ with $0\le n<k!$ has a unique expression
\[
n=\sum_{i=0}^{k-1}c_i i!,\qquad 0\le c_i<i+1.
\]
\end{corollary}
\begin{proof}
The range theorem makes the map well-defined and the uniqueness theorem makes it injective. Domain and codomain each contain $k!$ elements, so the map is surjective as well.
\end{proof}

\section{Recursive permutation ranks}

\begin{lemma}[Distinguished-element decomposition]
A permutation of $[k+1]$ is uniquely determined by a position $q\in\{0,\ldots,k\}$ occupied by the distinguished element $k$ and a permutation of the remaining ordered set $[k]$. Hence
\[
\Sn_{k+1}\cong [k+1]\times\Sn_k.
\]
\end{lemma}
\begin{proof}
Record the position of $k$, remove it, and retain the order of the remaining symbols. Conversely, insert $k$ at the recorded position. Removal and insertion are inverse operations.
\end{proof}

\begin{definition}[Recursive unranking]
Define $U_k:\{0,\ldots,k!-1\}\to\Sn_k$ recursively. Map $0$ to the empty permutation when $k=0$. Given $n<(k+1)!$, write uniquely
\[
n=qk!+r,\qquad 0\le q<k+1,\quad 0\le r<k!.
\]
Form $U_k(r)$ and insert the distinguished element $k$ at position $q$.
\end{definition}

\begin{definition}[Recursive ranking]
Define $R_0$ of the empty permutation to be $0$. For $\sigma\in\Sn_{k+1}$, remove $k$, let $q$ be its former position, and let $\tau\in\Sn_k$ be the remaining permutation. Set
\[
R_{k+1}(\sigma)=qk!+R_k(\tau).
\]
\end{definition}

\begin{theorem}[Recursive rank--unrank equivalence]
For every $k\in\N$, $U_k$ and $R_k$ are mutually inverse bijections between $\{0,\ldots,k!-1\}$ and $\Sn_k$.
\end{theorem}
\begin{proof}
Induct on $k$. At the successor step, Euclidean division uniquely decomposes a rank into a quotient in $[k+1]$ and a smaller rank. The distinguished-element lemma uniquely decomposes a permutation into a position and a smaller permutation. Quotient and remainder are recovered exactly, insertion and removal are inverse, and the induction hypothesis handles the smaller component.
\end{proof}

\section{The classification theorem}

\begin{definition}[Classified permutation]
For $c\in\C_k$, define
\[
\Phi_k(c)=U_k(V_k(c)).
\]
\end{definition}

\begin{theorem}[Factorial-Code Classification Theorem]
For every $k\in\N$, the map
\[
\Phi_k:\C_k\longrightarrow\Sn_k
\]
is a bijection. Its permutation rank is exactly its factoradic value:
\[
R_k(\Phi_k(c))=V_k(c)
\]
for every $c\in\C_k$.
\end{theorem}
\begin{proof}
Factoradic evaluation is a bijection from codes to ranks, and recursive unranking is a bijection from ranks to permutations. Their composition is therefore a bijection. Since $R_k$ is inverse to $U_k$,
\[
R_k(\Phi_k(c))=R_k(U_k(V_k(c)))=V_k(c).
\]
\end{proof}

\begin{corollary}[Unique code]
For every $\sigma\in\Sn_k$, there exists a unique $c\in\C_k$ such that $\Phi_k(c)=\sigma$.
\end{corollary}
\begin{proof}
Existence and uniqueness are respectively surjectivity and injectivity of $\Phi_k$.
\end{proof}

\begin{corollary}[Equality criteria]
For $c,d\in\C_k$,
\[
\Phi_k(c)=\Phi_k(d)\iff c=d\iff V_k(c)=V_k(d).
\]
\end{corollary}
\begin{proof}
The first equivalence is injectivity of $\Phi_k$ together with preservation of equality. The second is uniqueness of bounded factorial expansion together with preservation of equality by $V_k$.
\end{proof}

\begin{corollary}[Factorial enumeration]
For every $k\in\N$, $|\Sn_k|=k!$.
\end{corollary}
\begin{proof}
The classification is a bijection and $|\C_k|=k!$.
\end{proof}

\begin{example}[Small cardinalities]
For $k=0,1,2,3,4,5$, the common cardinalities of codes, ranks, and permutations are
\[
1,1,2,6,24,120.
\]
The base case consists of one empty code, one rank, and one empty permutation.
\end{example}

\section{Algorithms and complexity}

\begin{algorithm}[Factoradic digit extraction]
Given $0\le n<k!$, for $i=0,1,\ldots,k-1$ set
\[
c_i=n\bmod(i+1),\qquad n\leftarrow\left\lfloor\frac{n}{i+1}\right\rfloor.
\]
The result is the unique code with the original value.
\end{algorithm}

Each remainder lies in $\{0,\ldots,i\}$. Reversing the recurrence reconstructs the weighted factorial sum; uniqueness identifies the result. The method uses $k$ quotient--remainder operations, hence $O(k)$ unit-cost time and $O(k)$ output space.

\begin{algorithm}[Selection-based unranking]
Begin with $L=[0,1,\ldots,k-1]$. Read factorial digits from $c_{k-1}$ down to $c_0$. At step $i$, remove the item at zero-based index $c_i$ from $L$ and append it to the output.
\end{algorithm}

Before step $i$, the pool has $i+1$ elements, so the bound $c_i<i+1$ makes the operation valid. Every item is removed once. Conversely, an output permutation uniquely reveals each selected index. A list implementation costs $O(k^2)$ time and $O(k)$ space; an order-statistics tree gives $O(k\log k)$ time.

\begin{algorithm}[Selection-based ranking]
Given $p=(p_0,\ldots,p_{k-1})$, initialize $L=[0,\ldots,k-1]$. At step $j$, find the index $a_j$ of $p_j$ in $L$, remove it, and add
\[
a_j(k-1-j)!
\]
to the rank.
\end{algorithm}

The recorded indices are exactly the descending factorial digits used by unranking, so the algorithms are inverse. A list implementation is $O(k^2)$, while an order-statistics tree supports $O(k\log k)$ ranking.

\begin{example}
For $k=4$ and rank $17$, digit extraction gives
\[
(c_0,c_1,c_2,c_3)=(0,1,2,2),
\qquad
17=0\cdot0!+1\cdot1!+2\cdot2!+2\cdot3!.
\]
Selection from $[0,1,2,3]$ with descending digits $(2,2,1,0)$ gives $(2,3,1,0)$. Ranking this permutation returns $17$. Running through ranks $0$ to $23$ produces all $24$ permutations exactly once.
\end{example}

\section{Applications}

\subsection{Compact indexing}
A permutation can be represented by one integer in $[0,k!)$, close to the information-theoretic requirement of $\log_2(k!)$ bits. The factorial digits expose useful recursive structure for serialization, database keys, and reproducible identifiers.

\subsection{Exhaustive and parallel search}
Rank intervals divide exhaustive permutation search without overlap. The highest digit partitions the space into $k$ blocks of $(k-1)!$ permutations, and lower digits recursively subdivide those blocks. Unique representation guarantees complete, disjoint coverage.

\subsection{Uniform random generation}
A uniform rank unpacks to a uniform permutation because unranking is bijective. Equivalently, choose each $c_i$ independently and uniformly from $\{0,\ldots,i\}$. Every code, and hence every permutation, then has probability
\[
\prod_{i=0}^{k-1}\frac1{i+1}=\frac1{k!}.
\]

\subsection{Inversions and adjacency}
In the conventional selection interpretation, each digit counts available smaller entries skipped at a stage, linking factorial coordinates to inversion statistics. Incrementing rank produces mixed-radix carries, which induce structured changes in the associated permutation. These connections motivate parity formulas and efficient neighboring-permutation generation.

\subsection{Canonical testing and reproducibility}
The coordinate gives a direct testing protocol. For every $0\le n<k!$, one may check
\[
R_k(U_k(n))=n,
\]
and for every permutation $\sigma$ one may check
\[
U_k(R_k(\sigma))=\sigma.
\]
The first identity tests complete recovery of ranks; the second tests complete recovery of permutations. Together they detect omissions, collisions, and mismatched indexing conventions.

A rank becomes a portable description after fixing the order of the ground set and the insertion or selection orientation. Distinct valid conventions may enumerate the same permutations in different orders. The classification asserts that the specified arithmetic and combinatorial recursions are mutually inverse and that factoradic value is the rank within that fixed system.

\subsection{Information content and mixed-radix optimality}
The total information capacity of the digit ranges is
\[
\sum_{i=0}^{k-1}\log_2(i+1)=\log_2(k!),
\]
exactly the amount needed to distinguish $k!$ permutations. There are no unused legal codes and no collisions. A single binary rank can use $\lceil\log_2(k!)\rceil$ bits, while the factorial digits expose the recursive decisions used for ranking and unranking.

\section{Discussion}

The classification is governed by the parallel identity $(k+1)!=(k+1)k!$. Arithmetically, a number below $(k+1)!$ is a quotient below $k+1$ together with a remainder below $k!$. Combinatorially, a permutation of $k+1$ objects is a position for one distinguished object together with a permutation of the other $k$. Iterating the first decomposition creates factorial digits; iterating the second creates permutations.

Three logically separate facts are thereby joined. There are $k!$ legal codes. Their weighted values are distinct and exhaust the rank interval. Those ranks canonically determine permutations. The result is not merely a count but an explicit equality-preserving coordinate system with inverse procedures.

\section{Future directions}

\begin{enumerate}[leftmargin=*]
\item Develop a directly executable factorial-division decoder and compare recursive conventions extensionally.
\item Identify each digit with a precise preceding- or following-inversion count, thereby matching the conventional Lehmer semantics.
\item Prove the parity formula
\[
\operatorname{sgn}(\sigma)=(-1)^{\sum_i c_i}.
\]
\item Characterize the permutation transformation caused by incrementing rank, including mixed-radix carry propagation.
\item Transport the classification to arbitrary finite linearly ordered sets and establish naturality under order equivalences.
\item Establish precise time and bit-complexity bounds for rank and unrank, especially with order-statistics data structures.
\end{enumerate}

\section{Conclusion}

For every natural number $k$, bounded factorial codes, integers below $k!$, and permutations of $k$ elements are equivalent descriptions of one finite structure. Factorial evaluation is in range, injective, and therefore bijective. Recursive quotient--remainder decomposition mirrors recursive insertion of a distinguished element. Their composition gives a canonical correspondence whose permutation rank is
\[
\sum_{i=0}^{k-1}c_i i!.
\]
Every permutation has exactly one code, equality can be checked digitwise or numerically, and $|\Sn_k|=k!$ follows from an explicit reversible coordinate system.

\end{document}

